struct tree_node
{
    int color;
    tree_node *parent;
    tree_node *left;
    tree_node *right;
    char value[8];
};

struct tree_compare
{
    char value;
};

struct char_tree
{
    tree_node *header;
    unsigned int node_count;
    tree_compare key_compare;

    tree_node *&root() { return header->parent; }
    tree_node *root() const { return header->parent; }
    tree_node *&leftmost() { return header->left; }
    tree_node *&rightmost() { return header->right; }

    void erase(tree_node *);
    tree_node *copy(tree_node *, tree_node *);

    void clear()
    {
        if (node_count != 0)
        {
            erase(root());
            leftmost() = header;
            root() = 0;
            rightmost() = header;
            node_count = 0;
        }
    }

    char_tree &operator=(const char_tree &other);
};

