char_tree &char_tree::operator=(const char_tree &other)
{
    if (this != &other)
    {
        clear();
        key_compare = other.key_compare;
        if (other.root() == 0)
        {
            root() = 0;
            leftmost() = header;
            rightmost() = header;
        }
        else
        {
            root() = copy(other.root(), header);
            leftmost() = root();
            while (leftmost()->left != 0)
                leftmost() = leftmost()->left;
            rightmost() = root();
            while (rightmost()->right != 0)
                rightmost() = rightmost()->right;
            node_count = other.node_count;
        }
    }
    return *this;
}
